import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

const SAMPLE = {
  tasa_anual: 18.5,
  cuota_mensual: 4587.32,
  total_pagar: 55047.84,
};

function formatRate(value: number): string {
  return value.toFixed(2).replace('.', ',') + ' %';
}

function formatMoney(value: number): string {
  const [int, dec] = value.toFixed(2).split('.');
  return '$ ' + int.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec;
}

export default function Resultado({ navigate }: { navigate: (to: string) => void }) {
  const [showInfo, setShowInfo] = useState(true);

  const newSimulation = () => navigate('SCR-SIMULADOR');

  return (
    <Screen
      title="Resultado de tu simulación"
      code="SCR-RESULTADO"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nueva simulación', onPress: newSimulation, primary: true },
            { key: 'PF3', label: 'Volver', onPress: newSimulation },
          ]}
        />
      }
    >
      <Stack>
        {showInfo && (
          <Alert tone="success">
            Tu simulación se calculó correctamente. Los valores son informativos y no constituyen una oferta
            vinculante.
          </Alert>
        )}

        <Card
          title="Resultado de tu simulación"
          actions={<Badge>Simulación</Badge>}
        >
          <Grid columns={3}>
            <div data-field="tasa_anual">
              <TextField
                label="Tasa anual"
                value={formatRate(SAMPLE.tasa_anual)}
                onChange={() => {}}
                readOnly
                hint="Tasa nominal anual"
              />
            </div>
            <div data-field="cuota_mensual">
              <TextField
                label="Cuota mensual"
                value={formatMoney(SAMPLE.cuota_mensual)}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="total_pagar">
              <TextField
                label="Total a pagar"
                value={formatMoney(SAMPLE.total_pagar)}
                onChange={() => {}}
                readOnly
                hint="Suma de todas las cuotas"
              />
            </div>
          </Grid>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={newSimulation}>
            Nueva simulación
          </Button>
          {showInfo && (
            <Button variant="ghost" onClick={() => setShowInfo(false)}>
              Ocultar aviso
            </Button>
          )}
        </Row>
      </Stack>
    </Screen>
  );
}
